const STATUS_META = {
  real: { label: "REAL", icon: CheckCircle2, color: C.real, desc: "Extraído de fonte pública ou institucional do cliente" },
  meta: { label: "META", icon: Target, color: C.meta, desc: "Meta padrão da metodologia Lyrio ESG, aplicável a qualquer cliente" },
  aguardando: { label: "AGUARDANDO COLETA", icon: CircleDashed, color: C.wait, desc: "Preenchido no diagnóstico presencial deste cliente" },
};

const ALERT_META = {
  ok: { color: C.ok, label: "Dentro do esperado" },
  atencao: { color: C.warn, label: "Requer atenção" },
  critico: { color: C.crit, label: "Sem visibilidade" },
};

function StatusPill({ status, small }) {
  const s = STATUS_META[status];
  const Icon = s.icon;
  return (
    <span
      title={s.desc}
      className={`inline-flex items-center gap-1 rounded-full font-medium tracking-wide ${small ? "px-1.5 py-0.5 text-[9px]" : "px-2 py-0.5 text-[10px]"}`}
      style={{ backgroundColor: `${s.color}1A`, color: s.color, border: `1px solid ${s.color}55` }}
    >
      <Icon size={small ? 10 : 11} strokeWidth={2.5} />
      {s.label}
    </span>
  );
}

function AlertDot({ level }) {
  const a = ALERT_META[level];
  return <span className="inline-block w-2 h-2 rounded-full shrink-0" style={{ backgroundColor: a.color }} title={a.label} />;
}

function Sparkline({ data, color }) {
  if (!data || data.length < 2) return null;
  const w = 140, h = 36, max = Math.max(...data), min = Math.min(...data);
  const range = max - min || 1;
  const pts = data.map((v, i) => `${(i / (data.length - 1)) * w},${h - ((v - min) / range) * h}`).join(" ");
  return (
    <svg width={w} height={h} viewBox={`0 0 ${w} ${h}`}>
      <polyline points={pts} fill="none" stroke={color} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  );
}

