export default function LyrioESGPlatform() {
  const [showCover, setShowCover] = useState(true);
  const [clientId, setClientId] = useState("boulevard");
  const [switcherOpen, setSwitcherOpen] = useState(false);
  const [page, setPage] = useState("geral");
  const [activeKpi, setActiveKpi] = useState(null);
  const [mobileNavOpen, setMobileNavOpen] = useState(false);

  const client = CLIENTS[clientId];
  const KPIS = client.kpis;
  const byPillar = (p) => KPIS.filter((k) => k.pillar === p);
  const alertsList = KPIS.filter((k) => k.alerta !== "ok");
  const critCount = KPIS.filter((k) => k.alerta === "critico").length;
  const warnCount = KPIS.filter((k) => k.alerta === "atencao").length;

  const pickClient = (id) => {
    setClientId(id);
    setSwitcherOpen(false);
    setPage("geral");
    setActiveKpi(null);
  };

  const NavButton = ({ item, locked }) => {
    const Icon = item.icon;
    const active = page === item.id;
    return (
      <button
        onClick={() => { if (!locked) setPage(item.id); setMobileNavOpen(false); }}
        className="w-full flex items-center gap-2.5 rounded-xl px-3 py-2 text-sm transition-colors"
        style={{
          backgroundColor: active ? C.card : "transparent",
          color: active ? C.text : locked ? `${C.dim}99` : C.dim,
        }}
      >
        <Icon size={15} />
        <span className="flex-1 text-left">{item.label}</span>
        {locked && <Lock size={11} />}
        {item.id === "alertas" && (critCount + warnCount > 0) && (
          <span className="text-[10px] rounded-full px-1.5" style={{ backgroundColor: `${C.crit}22`, color: C.crit }}>{critCount + warnCount}</span>
        )}
      </button>
    );
  };

  const ClientSwitcher = ({ inDrawer }) => (
    <div className="relative">
      <button
        onClick={() => setSwitcherOpen((v) => !v)}
        className="w-full flex items-center gap-2.5 rounded-xl px-3 py-2.5 transition-colors"
        style={{ backgroundColor: C.navySoft, border: `1px solid ${C.navyLine}` }}
      >
        <Building2 size={16} style={{ color: "#8FB6E8" }} className="shrink-0" />
        <div className="min-w-0 text-left flex-1">
          <div className="text-sm font-medium truncate" style={{ color: "#F2EFE6" }}>{client.name}</div>
          <div className="text-[11px] truncate" style={{ color: "#8FA6C9" }}>{client.subtitle}</div>
        </div>
        <ChevronDown size={14} style={{ color: "#8FA6C9" }} className={`shrink-0 transition-transform ${switcherOpen ? "rotate-180" : ""}`} />
      </button>
      {switcherOpen && (
        <div
          className={`${inDrawer ? "relative mt-1" : "absolute left-0 right-0 mt-1 z-20"} rounded-xl overflow-hidden`}
          style={{ backgroundColor: C.navySoft, border: `1px solid ${C.navyLine}` }}
        >
          {Object.values(CLIENTS).map((c) => (
            <button
              key={c.id}
              onClick={() => pickClient(c.id)}
              className="w-full flex items-center gap-2 px-3 py-2.5 text-left"
              style={{ backgroundColor: c.id === clientId ? C.navyLine : "transparent" }}
            >
              <div className="flex-1 min-w-0">
                <div className="text-xs font-medium truncate" style={{ color: "#F2EFE6" }}>{c.name}</div>
                <div className="text-[10px] truncate" style={{ color: "#8FA6C9" }}>{c.sector}</div>
              </div>
              {c.id === clientId && <Check size={13} style={{ color: "#8FB6E8" }} />}
            </button>
          ))}
        </div>
      )}
    </div>
  );

  if (showCover) {
    return (
      <div
        className="min-h-screen w-full flex flex-col items-center justify-center gap-8 px-6 text-center"
        style={{ backgroundColor: C.navy, color: "#F2EFE6", fontFamily: "'IBM Plex Sans', sans-serif" }}
      >
        <style>{`@import url('https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@500;600;700&family=IBM+Plex+Sans:wght@400;500;600&family=IBM+Plex+Mono:wght@500;600&display=swap');`}</style>
        <img src={LOGO_FULL} alt="Lyrio ESG" className="w-64 sm:w-80 h-auto object-contain" />
        <div className="max-w-md flex flex-col gap-3">
          <h1 className="text-lg sm:text-xl font-medium" style={{ fontFamily: "'Space Grotesk', sans-serif" }}>
            Plataforma de Inteligência ESG
          </h1>
          <p className="text-sm" style={{ color: "#8FA6C9" }}>
            Uma arquitetura única, replicável para qualquer cliente — do diagnóstico ao score ESG, com o mesmo padrão de qualidade Lyrio.
          </p>
        </div>
        <button
          onClick={() => setShowCover(false)}
          className="rounded-full px-6 py-2.5 text-sm font-medium transition-colors"
          style={{ backgroundColor: C.env, color: C.navy }}
        >
          Entrar na plataforma
        </button>
      </div>
    );
  }

  return (
    <div className="min-h-screen w-full flex" style={{ backgroundColor: C.bg, color: C.text, fontFamily: "'IBM Plex Sans', sans-serif" }}>
      <style>{`@import url('https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@500;600;700&family=IBM+Plex+Sans:wght@400;500;600&family=IBM+Plex+Mono:wght@500;600&display=swap');`}</style>

      {/* SIDEBAR — desktop */}
      <aside className="hidden md:flex flex-col w-64 shrink-0" style={{ backgroundColor: C.sidebar, borderRight: `1px solid ${C.border}` }}>
        {/* CHROME DA PLATAFORMA — não muda com o cliente */}
        <div className="p-3 flex flex-col gap-3" style={{ backgroundColor: C.navy, borderBottom: `1px solid ${C.navyLine}` }}>
          <div className="flex items-center gap-2 px-1">
            <img src={LOGO_WORDMARK} alt="Lyrio ESG" className="h-6 w-auto object-contain" />
            <div className="ml-auto text-right">
              <div className="text-[9px] uppercase tracking-[0.14em]" style={{ color: "#8FA6C9" }}>Plataforma</div>
              <div className="text-[10px] font-medium" style={{ color: "#F2EFE6" }}>multi-cliente</div>
            </div>
          </div>
          <ClientSwitcher />
        </div>

        {/* WORKSPACE DO CLIENTE — navegação do produto */}
        <div className="flex-1 flex flex-col p-4 gap-1 overflow-y-auto">
          {NAV.map((item) => <NavButton key={item.id} item={item} />)}
          <div className="my-2 h-px" style={{ backgroundColor: C.border }} />
          {NAV_LOCKED.map((item) => <NavButton key={item.id} item={item} locked />)}
          <div className="mt-auto pt-3 flex items-center gap-2 px-2">
            <UserCircle2 size={22} style={{ color: C.dim }} />
            <div>
              <div className="text-xs font-medium">Daniel Lyrio</div>
              <div className="text-[10px]" style={{ color: C.dim }}>Consultor ESG · Lyrio</div>
            </div>
          </div>
        </div>
      </aside>

      {/* MOBILE NAV DRAWER */}
      {mobileNavOpen && (
        <div className="fixed inset-0 z-50 flex md:hidden" style={{ backgroundColor: "#00000099" }} onClick={() => setMobileNavOpen(false)}>
          <div className="w-72 h-full flex flex-col" style={{ backgroundColor: C.sidebar }} onClick={(e) => e.stopPropagation()}>
            <div className="p-3 flex flex-col gap-3" style={{ backgroundColor: C.navy, borderBottom: `1px solid ${C.navyLine}` }}>
              <img src={LOGO_WORDMARK} alt="Lyrio ESG" className="h-6 w-auto object-contain" />
              <ClientSwitcher inDrawer />
            </div>
            <div className="p-4 flex flex-col gap-1 overflow-y-auto">
              {NAV.map((item) => <NavButton key={item.id} item={item} />)}
              <div className="my-2 h-px" style={{ backgroundColor: C.border }} />
              {NAV_LOCKED.map((item) => <NavButton key={item.id} item={item} locked />)}
            </div>
          </div>
        </div>
      )}

      <div className="flex-1 flex flex-col min-w-0">
        {/* TOP BAR */}
        <header className="flex items-center gap-3 px-4 sm:px-6 py-3" style={{ borderBottom: `1px solid ${C.border}` }}>
          <button className="md:hidden" onClick={() => setMobileNavOpen(true)}><Menu size={20} /></button>
          <img src={LOGO_WORDMARK} alt="Lyrio ESG" className="h-5 w-auto object-contain md:hidden" />
          <div className="hidden md:flex items-center gap-2">
            <Sparkles size={14} style={{ color: C.env }} />
            <span className="text-[10px] uppercase tracking-[0.15em] rounded-full px-2 py-0.5" style={{ color: C.dim, border: `1px solid ${C.border}` }}>
              Plataforma Lyrio ESG · {client.sector}
            </span>
          </div>
          <div className="hidden sm:flex items-center gap-2 ml-4 flex-1 max-w-xs rounded-full px-3 py-1.5" style={{ backgroundColor: C.card, border: `1px solid ${C.border}` }}>
            <Search size={13} style={{ color: C.dim }} />
            <span className="text-xs" style={{ color: C.dim }}>Buscar indicador...</span>
          </div>
          <div className="ml-auto flex items-center gap-3">
            <div className="relative">
              <Bell size={17} style={{ color: C.dim }} />
              {(critCount + warnCount > 0) && <span className="absolute -top-1 -right-1 w-3.5 h-3.5 rounded-full text-[8px] flex items-center justify-center" style={{ backgroundColor: C.crit, color: "#fff" }}>{critCount + warnCount}</span>}
            </div>
            <UserCircle2 size={22} style={{ color: C.dim }} className="md:hidden" />
          </div>
        </header>

        <main className="flex-1 overflow-y-auto px-4 sm:px-6 py-6">
          {/* VISÃO EXECUTIVA */}
          {page === "geral" && (
            <div className="flex flex-col gap-6 max-w-5xl">
              <div className="flex flex-wrap items-center gap-6 rounded-2xl p-6" style={{ backgroundColor: C.card, border: `1px solid ${C.border}` }}>
                <div>
                  <div className="flex items-center gap-2 mb-1">
                    <span className="text-[11px] uppercase tracking-wider" style={{ color: C.dim }}>Score ESG (ilustrativo)</span>
                    <StatusPill status="meta" small />
                  </div>
                  {client.score !== null ? (
                    <div className="flex items-baseline gap-2">
                      <span className="text-5xl" style={{ fontFamily: "'IBM Plex Mono', monospace", fontWeight: 600 }}>{client.score}</span>
                      <span className="flex items-center gap-0.5 text-sm" style={{ color: C.real }}><TrendingUp size={14} /> {client.scoreDelta}</span>
                    </div>
                  ) : (
                    <div className="flex items-baseline gap-2">
                      <span className="text-5xl" style={{ fontFamily: "'IBM Plex Mono', monospace", fontWeight: 600, color: C.dim }}>—</span>
                      <span className="text-sm" style={{ color: C.dim }}>score liberado após diagnóstico</span>
                    </div>
                  )}
                  <p className="text-[11px] mt-1" style={{ color: C.dim }}>Cálculo automático real disponível após integração de dados</p>
                </div>
                <div className="h-12 w-px hidden sm:block" style={{ backgroundColor: C.border }} />
                <div className="flex gap-8 text-sm">
                  <div>
                    <p style={{ color: C.dim }} className="text-[11px]">Cliente ativo</p>
                    <p className="font-medium">{client.name}</p>
                  </div>
                  <div>
                    <p style={{ color: C.dim }} className="text-[11px]">Próxima auditoria</p>
                    <p className="font-medium">a agendar</p>
                  </div>
                  <div>
                    <p style={{ color: C.dim }} className="text-[11px]">Alertas ativos</p>
                    <p className="font-medium" style={{ color: (critCount + warnCount) ? C.warn : C.text }}>{critCount + warnCount}</p>
                  </div>
                </div>
              </div>

              <div className="flex flex-wrap gap-8 justify-center sm:justify-start rounded-2xl p-6" style={{ backgroundColor: C.card, border: `1px solid ${C.border}` }}>
                <DonutGauge percent={client.donuts.ambiental} color={C.env} label="Ambiental (E)" sub="maturidade estimada" />
                <DonutGauge percent={client.donuts.social} color={C.social} label="Social (S)" sub="maturidade estimada" />
                <DonutGauge percent={client.donuts.governanca} color={C.gov} label="Governança (G)" sub="maturidade estimada" />
              </div>

              <div>
                <h3 className="text-sm font-medium mb-3" style={{ color: C.text }}>Mapa de unidades <span className="font-normal" style={{ color: C.dim }}>— pronto para dado por loja, planta ou setor</span></h3>
                <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
                  {client.setores.map((s) => (
                    <div key={s.nome} className="rounded-xl p-3 flex items-center justify-between" style={{ backgroundColor: C.card, border: `1px solid ${C.border}` }}>
                      <span className="text-xs">{s.nome}</span>
                      <StatusPill status={s.status} small />
                    </div>
                  ))}
                </div>
              </div>

              <div className="grid sm:grid-cols-3 gap-4">
                {KPIS.slice(0, 3).map((k) => (
                  <KpiCard key={k.id} kpi={k} onOpen={setActiveKpi} />
                ))}
              </div>
            </div>
          )}

          {/* AMBIENTAL */}
          {page === "ambiental" && (
            <div className="flex flex-col gap-6 max-w-5xl">
              <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-4">
                {byPillar("ambiental").map((k) => <KpiCard key={k.id} kpi={k} onOpen={setActiveKpi} />)}
              </div>
              <div className="rounded-2xl p-4" style={{ backgroundColor: C.card, border: `1px solid ${C.border}` }}>
                <div className="flex items-center justify-between mb-2">
                  <h3 className="text-sm font-medium flex items-center gap-2"><TrendingDown size={15} style={{ color: C.env }} /> Inventário de GEE — Escopos 1, 2 e 3 (tCO₂e)</h3>
                  <StatusPill status="meta" />
                </div>
                {client.geeData ? (
                  <>
                    <p className="text-[11px] mb-2" style={{ color: `${C.dim}99` }}>Série ilustrativa (GHG Protocol / ISO 14064-1) — substituída pelo inventário real após o diagnóstico.</p>
                    <ResponsiveContainer width="100%" height={260}>
                      <LineChart data={client.geeData} margin={{ top: 5, right: 10, left: -10, bottom: 0 }}>
                        <CartesianGrid strokeDasharray="3 3" stroke={C.border} />
                        <XAxis dataKey="ano" stroke={C.dim} tick={{ fontSize: 11 }} />
                        <YAxis stroke={C.dim} tick={{ fontSize: 11 }} />
                        <Tooltip contentStyle={{ backgroundColor: C.bgSoft, border: `1px solid ${C.border}`, fontSize: 12 }} />
                        <Legend wrapperStyle={{ fontSize: 12 }} />
                        <Line type="monotone" dataKey="escopo1" name="Escopo 1" stroke={C.env} strokeWidth={2} dot={false} />
                        <Line type="monotone" dataKey="escopo2" name="Escopo 2" stroke={C.gov} strokeWidth={2} dot={false} />
                        <Line type="monotone" dataKey="escopo3" name="Escopo 3" stroke={C.social} strokeWidth={2} dot={false} />
                      </LineChart>
                    </ResponsiveContainer>
                  </>
                ) : (
                  <div className="flex flex-col items-center justify-center gap-2 py-10 text-center">
                    <CircleDashed size={18} style={{ color: C.wait }} />
                    <p className="text-xs" style={{ color: C.dim }}>Inventário de GEE aparece aqui assim que o diagnóstico deste cliente for concluído.</p>
                  </div>
                )}
              </div>
            </div>
          )}

          {/* SOCIAL */}
          {page === "social" && (
            <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-4 max-w-5xl">
              {byPillar("social").map((k) => <KpiCard key={k.id} kpi={k} onOpen={setActiveKpi} />)}
            </div>
          )}

          {/* GOVERNANÇA */}
          {page === "governanca" && (
            <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-4 max-w-5xl">
              {byPillar("governanca").map((k) => <KpiCard key={k.id} kpi={k} onOpen={setActiveKpi} />)}
            </div>
          )}

          {/* CENTRO DE EVIDÊNCIAS */}
          {page === "evidencias" && (
            <div className="max-w-5xl overflow-x-auto rounded-2xl" style={{ border: `1px solid ${C.border}` }}>
              <table className="w-full text-sm" style={{ borderCollapse: "collapse" }}>
                <thead>
                  <tr style={{ backgroundColor: C.card }}>
                    {["Indicador", "Fonte", "Atualizado", "Confiabilidade", "Status"].map((h) => (
                      <th key={h} className="text-left px-3 py-2.5 text-[11px] uppercase tracking-wider font-medium" style={{ color: C.dim }}>{h}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {KPIS.map((k, i) => (
                    <tr key={k.id} onClick={() => setActiveKpi(k)} className="cursor-pointer" style={{ backgroundColor: i % 2 ? C.bgSoft : "transparent", borderTop: `1px solid ${C.border}` }}>
                      <td className="px-3 py-2.5">{k.label}</td>
                      <td className="px-3 py-2.5" style={{ color: C.dim }}>{k.fonte || "a definir"}</td>
                      <td className="px-3 py-2.5" style={{ color: C.dim }}>{k.atualizado || "—"}</td>
                      <td className="px-3 py-2.5" style={{ color: C.dim }}>{k.confiabilidade}%</td>
                      <td className="px-3 py-2.5"><StatusPill status={k.status} small /></td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}

          {/* ALERTAS */}
          {page === "alertas" && (
            <div className="flex flex-col gap-3 max-w-3xl">
              {["critico", "atencao"].map((lvl) => (
                <div key={lvl}>
                  <h3 className="text-xs uppercase tracking-wider mb-2" style={{ color: ALERT_META[lvl].color }}>{ALERT_META[lvl].label}</h3>
                  <div className="flex flex-col gap-2 mb-4">
                    {alertsList.filter((k) => k.alerta === lvl).map((k) => (
                      <button key={k.id} onClick={() => setActiveKpi(k)} className="flex items-center gap-3 rounded-xl p-3 text-left" style={{ backgroundColor: C.card, border: `1px solid ${C.border}` }}>
                        <AlertDot level={k.alerta} />
                        <div className="flex-1">
                          <p className="text-sm">{k.label}</p>
                          <p className="text-[11px]" style={{ color: C.dim }}>{k.note}</p>
                        </div>
                        <ChevronRight size={14} style={{ color: C.dim }} />
                      </button>
                    ))}
                  </div>
                </div>
              ))}
              {alertsList.length === 0 && <p className="text-sm" style={{ color: C.dim }}>Nenhum alerta ativo.</p>}
            </div>
          )}

          {/* ROADMAP */}
          {page === "roadmap" && (
            <div className="flex flex-col gap-3 max-w-3xl">
              {client.roadmap.map((r, i) => (
                <div key={i} className="flex items-center gap-4 rounded-2xl p-4" style={{ backgroundColor: C.card, border: `1px solid ${C.border}` }}>
                  <span className="text-sm font-medium rounded-full px-3 py-1 shrink-0" style={{ fontFamily: "'IBM Plex Mono', monospace", backgroundColor: `${C.env}1A`, color: C.env, border: `1px solid ${C.env}55` }}>{r.ano}</span>
                  <ChevronRight size={14} style={{ color: C.dim }} className="shrink-0" />
                  <span className="text-sm">{r.texto}</span>
                </div>
              ))}
            </div>
          )}

          {/* LOCKED PAGES */}
          {page === "usuarios" && <LockedPage label="Usuários & Permissões" />}
          {page === "integracoes" && <LockedPage label="Integrações" />}
          {page === "config" && <LockedPage label="Configurações" />}
        </main>

        <footer className="px-4 sm:px-6 py-4 text-[11px] flex flex-wrap items-center justify-between gap-2" style={{ color: `${C.dim}99`, borderTop: `1px solid ${C.border}` }}>
          <span>Lyrio ESG · Plataforma de Inteligência ESG · Resp. Técnico: Daniel Lyrio</span>
          <span>Cliente ativo: {client.name} · Protótipo navegável, pronto para dados reais</span>
        </footer>
      </div>

      <KpiModal kpi={activeKpi} onClose={() => setActiveKpi(null)} />
    </div>
  );
}
